import json, collections
runs=['9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7','53597ebc133c7eb0dff1937725f3b72f1c09b4b5','0d30915e47bd94e37ce6b62f68b611bff0458b14','13b8664bc78f4264c10a36e67028dfdb45cecde2']
pool=collections.defaultdict(dict)
def parse(s): return {p.strip().lower() for p in s.strip().split('.') if p.strip()}
for r in runs:
    for line in open(f'{r}/results/samples.jsonl'):
        d=json.loads(line)
        pool[d['task']].setdefault(d['example_index'],[]).append((d['prediction'],d['target'],d['was_correct']))
for task in ['USPTO','Symptom2Disease','LawBench']:
    exs=pool[task]
    print('='*10,task,'examples',len(exs),'pool sizes',collections.Counter(len(v) for v in exs.values()))
    base=sum(c for v in exs.values() for _,_,c in v)/sum(len(v) for v in exs.values())
    modal_correct=0;n=0
    for e,v in exs.items():
        cnt=collections.Counter(p for p,_,_ in v)
        top,c=cnt.most_common(1)[0]
        modal_correct += 1 if top==v[0][1] else 0
        n+=1
    print('  per-sample acc %.3f | modal-of-pool acc %.3f'%(base, modal_correct/n))
    if task=='USPTO':
        for thr in [0.5, 0.34]:
            comp_ok=0
            for e,v in exs.items():
                k=len(v); gold=parse(v[0][1]); cnt=collections.Counter()
                for p,_,_ in v:
                    for comp in parse(p): cnt[comp]+=1
                maj={c for c,ct in cnt.items() if ct>k*thr}
                comp_ok += 1 if maj==gold else 0
            print('  component-majority(>%.2f) acc %.3f'%(thr,comp_ok/n))
    if task=='LawBench':
        import re
        def pch(s):
            s=re.sub(r"\[罪名\](.*?)(?:<eoa>|$)","\\1",s.strip())
            for sep in [";","；",",","，","、"]:
                if sep in s: return {p.strip() for p in s.split(sep) if p.strip()}
            return {s.strip()} if s.strip() else set()
        comp_ok=0
        for e,v in exs.items():
            k=len(v); gold=pch(v[0][1]); cnt=collections.Counter()
            for p,_,_ in v:
                for comp in pch(p): cnt[comp]+=1
            maj={c for c,ct in cnt.items() if ct*2>k}
            comp_ok += 1 if maj==gold else 0
